/** Distinct not-yet-correct concepts in an actual topic.
 * Once any question version was correct, that concept is not new again.
 * Unknown topics return null rather than a fabricated supply count. */
export function latinDailyUncreditedConcepts(topicId,seenCorrect={}){
  const groups=SOURCE_GROUPS[String(topicId||'')];
  if(!groups)return null;
  return groups.filter(ids=>ids.every(id=>!(Number(seenCorrect?.[id])>0))).length;
}
